import re
import subprocess
import sys
from pathlib import Path


def scrivi_input(cartella, F, k):
    cartella = Path(cartella)
    cartella.mkdir(parents=True, exist_ok=True)
    f = cartella / "caso.inp"
    f.write_text(f"F={F}\nk={k}\n")
    return f


def esegui(cartella, programma):
    r = subprocess.run([sys.executable, str(Path(programma).resolve()), "caso.inp"], cwd=cartella,
                       capture_output=True, text=True, timeout=30)
    if r.returncode != 0:
        righe = r.stderr.strip().splitlines() or ["errore sconosciuto"]
        raise RuntimeError(righe[-1])
    m = re.search(r"spostamento = ([-\d.eE+]+) mm", r.stdout)
    if m is None:
        raise RuntimeError("output senza spostamento")
    return float(m.group(1))


def studio(base, programma, carichi, k):
    out = {}
    for F in carichi:
        cartella = Path(base) / f"F{F}"
        scrivi_input(cartella, F, k)
        try:
            out[F] = esegui(cartella, programma)
        except RuntimeError:
            out[F] = None
    return out
